#include "history.h"
#include <stdio.h>
static void menu(void){puts("\n========== BROWSER HISTORY ==========");puts("1. Visit New Page\n2. Go Back\n3. Go Forward\n4. Show Browsing History\n5. Search History\n6. Delete a History Entry\n7. Clear All History\n8. Show Current Page\n9. Show Statistics\n10. Exit");}
int main(void){int running=1;while(running){long choice;menu();if(!read_number("Choose an option: ",&choice)){if(feof(stdin))break;puts("Invalid input. Enter a number from 1 to 10.");continue;}switch(choice){case 1:visit_page();break;case 2:go_back();break;case 3:go_forward();break;case 4:show_history();break;case 5:search_history();break;case 6:delete_history_entry();break;case 7:{char answer[32];if(!history_count){puts("History is already empty.");break;}if(read_line("Clear all history? (y/n): ",answer,sizeof answer)&&(answer[0]=='y'||answer[0]=='Y')){clear_history();puts("All history cleared.");}else puts("Clear cancelled.");break;}case 8:show_current();break;case 9:show_statistics();break;case 10:running=0;break;default:puts("Invalid menu option. Choose 1-10.");}}clear_history();puts("Browser History System closed. Memory cleaned up.");return 0;}
